def affected(arr) -> bool:
    # Exact when the tail contains a zero (mutant raises ZeroDivisionError)
    # or when the input is too short for the min_ending difference to matter.
    # For longer nonzero inputs with some |n| >= 2 this is a conservative
    # approximation: the divergence may be masked, so it can over-report.
    tail = arr[1:]
    if 0 in tail:
        return True
    if len(arr) < 3:
        return False
    return any(abs(n) != 1 for n in tail)
